description:
Design a D-type flip-flop with asynchronous preset (PRE) and clear (CLR) functionalities. The output QN is set high when PRE is asserted, while CLR resets QN to low and QNF to high. On a rising edge of the CLK signal, if D is high, QN is set high and QNF low; if D is low, QN is set low and QNF high. This module effectively serves as a bistable element with control signals for initialization and synchronous data storage.
module top_module(PRE,CLR,CLK,D,QN,QNF
    );

code:
module top_module(PRE,CLR,CLK,D,QN,QNF
    );input PRE,CLR,CLK,D;
	output reg QN,QNF;

	always @(posedge CLK or negedge PRE or negedge CLR)
	begin
		if(!PRE)
			begin
				QN<=1;
				QNF<=0;
			end
		else if(!CLR)
			begin
				QN<=0;
				QNF<=1;
			end
		else if(CLK==0)
			begin
				;
			end
		else if(D==0)
			begin
				QN<=0;
				QNF<=1;
			end
		else
			begin
				QN<=1;
				QNF<=0;
			end
	end

endmodule

