Implement a circuit that performs an 8-bit bit-reversal operation on the input vector. The module takes an 8-bit wide input and outputs a vector with its bits in reverse order, so that the least significant bit becomes the most significant bit and vice versa.
module top_module(
  input [7:0] in_vector,
  output [7:0] out_vector
);

code:
module top_module(
  input [7:0] in_vector,
  output [7:0] out_vector
);reg [7:0] temp_vector;

  always @(*) begin
    temp_vector[0] = in_vector[7];
    temp_vector[1] = in_vector[6];
    temp_vector[2] = in_vector[5];
    temp_vector[3] = in_vector[4];
    temp_vector[4] = in_vector[3];
    temp_vector[5] = in_vector[2];
    temp_vector[6] = in_vector[1];
    temp_vector[7] = in_vector[0];
  end

  assign out_vector = temp_vector;

endmodule

