description:
Design a circuit that converts a 3-bit binary number into its corresponding 3-bit Gray code representation. The module utilizes XOR gates to compute the necessary conversions from binary to Gray code, ensuring that only one bit changes at a time when transitioning between consecutive values. The output is structured so that the most significant bit of the Gray code is derived from the most significant bit of the binary input, followed by further transformations of the remaining bits through logical operations.
module top_module(
  input [2:0] bin,
  output [2:0] gray
);

code:
module top_module(
  input [2:0] bin,
  output [2:0] gray
);wire x1, x2, x3, x4, x5, x6;

  // XOR gates
  xor(x1, bin[2], bin[1]);
  xor(x2, bin[1], bin[0]);
  xor(x3, bin[2], x1);
  xor(x4, bin[1], x2);
  xor(x5, bin[0], x4);

  // AND gates
  and(x6, x3, x5);

  assign gray = {x6, x5, x4};

endmodule

