module top_module(clk, res, a, b, outp);input clk,res;
  input [31:0] a, b;
  reg [7:0] exp_a,exp_b;
  output reg [8:0] outp;

  always @(posedge clk)
    begin
      exp_a = a[30:23];
      exp_b = b[30:23];
      if(exp_a >= exp_b)
        begin
        outp[7:0] = exp_a - exp_b;
        outp[8] = 0;
        end
      else
        begin
          outp[7:0] = exp_b - exp_a;
