module top_module(
	cw_from_cu, 
	mux_op, 
	cw_from_mux);input [22:0] cw_from_cu;
   input mux_op;
   output [22:0] cw_from_mux;

   // Internal wires
   wire n2;

   // Generate n2
   assign n2 = ~mux_op;

   // Implement the multiplexing logic
   assign cw_from_mux[0] = cw_from_cu[0] & n2;
   assign cw_from_mux[1] = cw_from_cu[1] & n2;
   assign cw_from_mux[2] = cw_from_cu[2] & n2;
