  input clk,
  input [7:0] ctrl,
  input [15:0] period,
  output reg pwm
);reg [15:0] counter;
reg [7:0] threshold;

always @(posedge clk) begin
  counter <= counter + 1;
  if (counter >= period) begin
    counter <= 0;
    threshold <= ctrl;
  end
  if (counter < threshold) begin
    pwm <= 1;
  end else begin
    pwm <= 0;
  end
end

endmodule

