module fsm_control (
        input clk,
        input reset,
        input e,
        output reg z);parameter U=0, V=1, W=2, X=3;
	reg [1:0] state, next;

	always @(posedge clk)
		if (reset)
			state <= U;
		else 
			state <= next;

	always_comb begin
		case(state)
			U: next = e ? W : V;
			V: next = e ? U : X;
			W: next = e ? X : U;
			X: next = e ? W : V;
			default: next = 'x;
		endcase
	end

	assign z = (state == U || state == W);

endmodule

