module top_module(clk, resetn, c_writedatain,
                c_reg, b_reg, a_reg, c_we, b_en, a_en,
                b_readdataout, a_readdataout);parameter WIDTH = 32;
    parameter NUMREGS = 32;
    parameter LOG2NUMREGS = 5;

    input clk;
    input resetn;

    input a_en;
    input b_en;
    input [31:0] c_writedatain;
    input c_we;
    input [31:0] a_reg;
    input [31:0] b_reg;
    input [31:0] c_reg;
    output [31:0] a_readdataout;
    output [31:0] b_readdataout;

    wire [31:0] a_readdataout_temp;
    wire [31:0] b_readdataout_temp;

    assign b_readdataout = b_readdataout_temp;
    assign a_readdataout = a_readdataout_temp;

    // Define a dual-port RAM to store the register file
    reg [WIDTH-1:0] regfile [0:NUMREGS-1];

    // Read ports
    assign a_readdataout_temp = (a_en) ? regfile[a_reg[LOG2NUMREGS-1:0]] : 32'b0;
    assign b_readdataout_temp = (b_en) ? regfile[b_reg[LOG2NUMREGS-1:0]] : 32'b0;

    // Write port
    always @(posedge clk) begin
        if (!resetn) begin
            integer i;
            for (i = 0; i < NUMREGS; i = i + 1) begin
                regfile[i] <= 32'b0;
            end
        end else if (c_we & (|c_reg)) begin
            regfile[c_reg[LOG2NUMREGS-1:0]] <= c_writedatain;
        end
    end

endmodule

