module parking_system (
	input clk,
	input resetn,
	input car_in,
	input car_out,
	output full);

	parameter EMPTY=0, ONE_CAR=1, TWO_CARS=2, FULL=10;
	reg [3:0] state, next_state;

	always @(posedge clk) begin
		if (~resetn) state <= EMPTY;
		else state <= next_state;
	end

	always_comb begin
		case (state)
			EMPTY: next_state = car_in ? ONE_CAR : EMPTY;
			ONE_CAR: next_state = car_out ? EMPTY : (car_in ? TWO_CARS : ONE_CAR);
			TWO_CARS: next_state = car_out ? ONE_CAR : (car_in ? FULL : TWO_CARS);
			FULL: next_state = car_out ? (FULL-1) : FULL;
			default: next_state = EMPTY;
		endcase
	end

	assign full = (state == FULL);
endmodule

