code:
module top_module(
	input clk,
	input enable,
	input reset,
	output reg [3:0] q);always @(posedge clk or posedge reset) begin
	if (reset)
		q <= 4'b0000;
	else if (enable)
		q <= q + 1;
end
endmodule

