module top_module(clk, q, signal, info);input clk, q;
	output reg signal;
	output wire info;
	reg[11:0] cnt;
	wire[11:0] cnt_nxt;
	assign cnt_nxt = cnt +1'b1;
	always@(posedge clk)begin
		if(!signal)begin
			if(!q)begin
				signal <= 1;
			end
		end
		else begin	
			if(cnt != 11'b10100000000)begin
				cnt = cnt_nxt;
			end
			else begin
				signal <= 0;
				cnt <= 11'b0;
			end
		end
	end
	assign info = q;endmodule

