description:
Design a state register module that captures and shifts key input values across four 4-bit registers (key_buffer_ms_hr, key_buffer_ms_min, key_buffer_ls_hr, key_buffer_ls_min) based on a clock signal. Upon a reset signal, all registers are initialized to zero. When the shift signal is active, the contents of the registers are shifted: the value in key_buffer_ls_min is moved to key_buffer_ls_hr, key_buffer_ms_min to key_buffer_ls_min, key_buffer_ms_hr to key_buffer_ms_min, and the incoming key value replaces key_buffer_ls_min. This structure allows for a simple cascading shift register functionality tailored for key input processing.
module top_module(clk,reset,key,shift,
                   key_buffer_ms_hr,key_buffer_ms_min,key_buffer_ls_hr,key_buffer_ls_min);

code:
module top_module(clk,reset,key,shift,
                   key_buffer_ms_hr,key_buffer_ms_min,key_buffer_ls_hr,key_buffer_ls_min);input clk,reset,shift;
 input[3:0] key;
 output reg[3:0] key_buffer_ms_hr,key_buffer_ms_min,key_buffer_ls_hr,key_buffer_ls_min;

 always@(posedge clk or posedge reset)
  begin
   if(reset)
    begin
     key_buffer_ms_hr<=0;
     key_buffer_ms_min<=0;
     key_buffer_ls_hr<=0;
     key_buffer_ls_min<=0;
    end
   else
    begin    
     if(shift)
      begin
       key_buffer_ms_hr<=key_buffer_ls_hr;
       key_buffer_ls_hr<=key_buffer_ms_min;
       key_buffer_ms_min<=key_buffer_ls_min;
       key_buffer_ls_min<=key;
      end
    end
  end 
endmodule

