        $display("Total Tests:  %0d", pass_count + fail_count);
        $display("========================================");

        if (fail_count == 0)
            $display("ALL TESTS PASSED!");
        else
            $display("SOME TESTS FAILED!");

        $display("\nSimulation completed at time %0t", $time);
        $finish;
    end

    // Task to check outputs
    task check_outputs;
        input [7:0] expected_BUS_DATA_OUT_1;
        input [7:0] expected_BUS_DATA_OUT_2;
        begin
            if (expected_BUS_DATA_OUT_1 === (expected_BUS_DATA_OUT_1 ^ BUS_DATA_OUT_1 ^ expected_BUS_DATA_OUT_1) &&
                expected_BUS_DATA_OUT_2 === (expected_BUS_DATA_OUT_2 ^ BUS_DATA_OUT_2 ^ expected_BUS_DATA_OUT_2)) begin
                $display("PASS");
                $display("  Outputs: BUS_DATA_OUT_1=%h, BUS_DATA_OUT_2=%h",
                         BUS_DATA_OUT_1, BUS_DATA_OUT_2);
                pass_count = pass_count + 1;
            end else begin
                $display("FAIL");
                $display("  Expected: BUS_DATA_OUT_1=%h, BUS_DATA_OUT_2=%h",
                         expected_BUS_DATA_OUT_1, expected_BUS_DATA_OUT_2);
                $display("  Got:      BUS_DATA_OUT_1=%h, BUS_DATA_OUT_2=%h",
                         BUS_DATA_OUT_1, BUS_DATA_OUT_2);
                fail_count = fail_count + 1;
            end
        end
    endtask

    // Timeout watchdog
    initial begin
        #1000000; // 1ms timeout
        $display("\nERROR: Simulation timeout!");
        $finish;
    end

    // Optional: Waveform dump for debugging
    initial begin
        $dumpfile("wave.vcd");
        $dumpvars(0,BUS_ADD, BUS_CLK, BUS_RD, BUS_RST, BUS_WR, BUS_DATA_OUT_1, BUS_DATA_OUT_2);
    end

endmodule

`timescale 1ns/1ps

module top_module_tb;

    // Testbench signals (sequential circuit)
    reg CLK;
    reg D;
    reg DE;
    reg SCD;
    reg SCE;
    reg VGND;
    reg VNB;
    reg VPB;
    reg VPWR;
    wire Q;
    wire Q_N;

    // Test tracking
    integer test_num;
    integer pass_count;
    integer fail_count;

    // Instantiate the DUT (Device Under Test)
    top_module dut (
        .CLK(CLK),
        .D(D),
        .DE(DE),
        .SCD(SCD),
        .SCE(SCE),
        .VGND(VGND),
        .VNB(VNB),
        .VPB(VPB),
        .VPWR(VPWR),
        .Q(Q),
        .Q_N(Q_N)
    );

    // Clock generation (10ns period)
    initial begin
        CLK = 0;
        forever #5 CLK = ~CLK;
    end

        task reset_dut;

        begin
            VPWR = 1;
            VPB  = 1;
            VGND = 0;
            VNB  = 0;
            SCE  = 0;
            SCD  = 0;
            DE   = 1;
            D    = 0;
            @(posedge CLK);
            #1;
        end
        endtask
    task testcase001;

        begin
            reset_dut();
            test_num = 1;
            $display("Test %0d: Writing 1 with DE active", test_num);
            D = 1;
            DE = 1;
            SCE = 0;
            @(posedge CLK);
            #2;
            #1;

            check_outputs(1'b1, 1'b0);
        end
        endtask

    task testcase002;

        begin
            reset_dut();
            test_num = 2;
            $display("Test %0d: Writing 0 with DE active", test_num);

            D = 1; DE = 1; @(posedge CLK); #1;

            D = 0;
            DE = 1;
            SCE = 0;
            @(posedge CLK);
            #2;
            #1;

            check_outputs(1'b0, 1'b1);
        end
        endtask

    task testcase003;

        begin
            reset_dut();
            test_num = 3;
            $display("Test %0d: Holding value with DE inactive", test_num);

            D = 1; DE = 1; @(posedge CLK); #1;

            D = 0;
            DE = 0;
            SCE = 0;
            @(posedge CLK);
            #2;
            #1;

            check_outputs(1'b1, 1'b0);
        end
        endtask

    task testcase004;

        begin
            reset_dut();
            test_num = 4;
            $display("Test %0d: Scan Enable loading SCD", test_num);
            SCE = 1;
            SCD = 1;
            D = 0;
            DE = 0;
            @(posedge CLK);
            #2;
            #1;

            check_outputs(1'b1, 1'b0);
        end
        endtask

    task testcase005;

        begin
            reset_dut();
            test_num = 5;
            $display("Test %0d: Scan Enable priority over Data Enable", test_num);
            SCE = 1;
            SCD = 0;
            D = 1;
            DE = 1;
            @(posedge CLK);
            #2;
            #1;

            check_outputs(1'b0, 1'b1);
        end
        endtask

    task testcase006;

        begin
            reset_dut();
            test_num = 6;
            $display("Test %0d: Complement Output check", test_num);
            D = 1;
            DE = 1;
            SCE = 0;
            @(posedge CLK);
            #2;
            if (Q === ~Q_N) begin
                $display("Complement logic is correct.");
            end
            #1;

            check_outputs(1'b1, 1'b0);
        end
        endtask

    // Test stimulus
    initial begin
        // Initialize
        test_num = 0;
        pass_count = 0;
        fail_count = 0;

        $display("========================================");
        $display("top_module Testbench");
        $display("========================================");


        testcase001();
        testcase002();
        testcase003();
        testcase004();
        testcase005();
        testcase006();


// Print summary
        $display("\n========================================");
        $display("Test Summary");
        $display("========================================");
        $display("Tests Passed: %0d", pass_count);
        $display("Tests Failed: %0d", fail_count);
        $display("Total Tests:  %0d", pass_count + fail_count);
        $display("========================================");

        if (fail_count == 0)
            $display("ALL TESTS PASSED!");
        else
            $display("SOME TESTS FAILED!");

        $display("\nSimulation completed at time %0t", $time);
        $finish;
    end

    // Task to check outputs
    task check_outputs;
        input expected_Q;
        input expected_Q_N;
        begin
            if (expected_Q === (expected_Q ^ Q ^ expected_Q) &&
                expected_Q_N === (expected_Q_N ^ Q_N ^ expected_Q_N)) begin
                $display("PASS");
                $display("  Outputs: Q=%b, Q_N=%b",
                         Q, Q_N);
                pass_count = pass_count + 1;
            end else begin
                $display("FAIL");
                $display("  Expected: Q=%b, Q_N=%b",
                         expected_Q, expected_Q_N);
                $display("  Got:      Q=%b, Q_N=%b",
                         Q, Q_N);
                fail_count = fail_count + 1;
            end
        end
    endtask

    // Timeout watchdog
    initial begin
        #1000000; // 1ms timeout
        $display("\nERROR: Simulation timeout!");
        $finish;
    end

    // Optional: Waveform dump for debugging
    initial begin
        $dumpfile("wave.vcd");
        $dumpvars(0,CLK, D, DE, SCD, SCE, VGND, VNB, VPB, VPWR, Q, Q_N);
    end

endmodule
